"""Embedded TrueType font binaries for 100% portable cross-platform rendering."""
import os
import base64

FONTS_DATA = {
    "Verdana-Regular.ttf": "",
    "Verdana-Bold.ttf": "",
    "Tahoma-Regular.ttf": "",
    "Tahoma-Bold.ttf": "",
}

def ensure_fonts_extracted():
    """Extracts TrueType fonts to ./fonts/ directory if not present."""
    base_dir = os.path.dirname(os.path.abspath(__file__))
    target_dir = os.path.join(base_dir, "fonts")
    os.makedirs(target_dir, exist_ok=True)
    for f_name, b64_data in FONTS_DATA.items():
        out_path = os.path.join(target_dir, f_name)
        if not os.path.exists(out_path) or os.path.getsize(out_path) == 0:
            with open(out_path, "wb") as f:
                f.write(base64.b64decode(b64_data))
